export const CalculatorWidgetContent: React.FC<{ widget: any, currentIsLight: boolean }> = ({ currentIsLight }) => {
  const [calc, setCalc] = useState("0");
  
  const handleBtn = (val: string) => {
    setCalc(prev => prev === "0" && val !== "." ? val : (prev + val).slice(0, 16));
  };
  const handleEval = () => {
    try {
      const res = evaluateCalculatorExpression(calc).toString();
      setCalc(res.length > 16 ? "Error" : res);
    } catch { setCalc("Error"); setTimeout(() => setCalc("0"), 1000) }
  };

  const btnClass = `flex-1 py-1 rounded shadow-sm text-sm font-bold transition-transform active:scale-95 border cursor-pointer flex items-center justify-center ${currentIsLight ? 'bg-white border-slate-200 text-slate-800 hover:bg-slate-50' : 'bg-white/5 border-white/10 text-white hover:bg-white/10'}`;
  
  return (
    <div className="flex flex-col h-full w-full p-2 gap-1.5 pointer-events-auto min-h-0">
      <div className={`w-full text-right p-2 rounded-lg text-xl font-mono tracking-wider overflow-hidden truncate font-black shadow-inner ${currentIsLight ? 'bg-slate-100 text-slate-800 border border-slate-200' : 'bg-black/50 text-emerald-400 border border-white/5'}`}>
        {calc}
      </div>
      <div className="flex-grow flex flex-col gap-1 min-h-0">
        <div className="flex gap-1 flex-1">
          <button onClick={() => setCalc("0")} className={btnClass + " text-rose-500"}>C</button>
          <button onClick={() => setCalc(prev => prev.length > 1 && prev !== "Error" ? prev.slice(0,-1) : "0")} className={btnClass}>DEL</button>
          <button onClick={() => handleBtn("%")} className={btnClass}>%</button>
          <button onClick={() => handleBtn("/")} className={btnClass + " text-indigo-500"}>/</button>
        </div>
        <div className="flex gap-1 flex-1">
          <button onClick={() => handleBtn("7")} className={btnClass}>7</button>
          <button onClick={() => handleBtn("8")} className={btnClass}>8</button>
          <button onClick={() => handleBtn("9")} className={btnClass}>9</button>
          <button onClick={() => handleBtn("x")} className={btnClass + " text-indigo-500"}>x</button>
        </div>
        <div className="flex gap-1 flex-1">
          <button onClick={() => handleBtn("4")} className={btnClass}>4</button>
          <button onClick={() => handleBtn("5")} className={btnClass}>5</button>
          <button onClick={() => handleBtn("6")} className={btnClass}>6</button>
          <button onClick={() => handleBtn("-")} className={btnClass + " text-indigo-500"}>-</button>
        </div>
        <div className="flex gap-1 flex-1">
          <button onClick={() => handleBtn("1")} className={btnClass}>1</button>
          <button onClick={() => handleBtn("2")} className={btnClass}>2</button>
          <button onClick={() => handleBtn("3")} className={btnClass}>3</button>
          <button onClick={() => handleBtn("+")} className={btnClass + " text-indigo-500"}>+</button>
        </div>
        <div className="flex gap-1 flex-1">
          <button onClick={() => handleBtn("0")} className={btnClass + " flex-[2.1]"}>0</button>
          <button onClick={() => handleBtn(".")} className={btnClass}>.</button>
          <button onClick={handleEval} className={`flex-1 flex items-center justify-center py-1 rounded shadow-sm text-sm font-bold transition-transform cursor-pointer active:scale-95 bg-indigo-500 hover:bg-indigo-600 text-white`}>=</button>
        </div>
      </div>
    </div>
  );
};

